"하루가 시작될 때 그날의 예산이 잠긴 후 토지의 무게에 따라 실시간으로 각 광맥에 할당됩니다. 채굴 풀이 적게 남을수록 이후의 일일 생산량도 적어집니다.",
"Vào đầu mỗi ngày, ngân sách trong ngày được khóa và sau đó được phân bổ cho từng mạch khoáng sản theo thời gian thực theo trọng lượng của thửa đất. Nhóm khai thác còn lại càng ít thì sản lượng hàng ngày tiếp theo sẽ càng ít.",
"في بداية كل يوم، يتم قفل ميزانية اليوم، ومن ثم يتم تخصيصها لكل عرق معدني في الوقت الحقيقي وفقًا لوزن قطعة الأرض. كلما قل عدد التعدين المتبقي، قل الإنتاج اليومي اللاحق."
